import { ACTIVE, HttpError, expandPath, validateProject } from './model.mjs';

// An import represents a project's current configuration. Match by id first,
// then directory so manifests generated by another tool remain repeatable.
export function planImport(input, existing = [], runs = []) {
  if (input?.schemaVersion !== 1 || !Array.isArray(input.projects) || input.projects.length > 1000) {
    throw new HttpError(400, '需要 schemaVersion 为 1、包含 0–1000 个项目的 JSON');
  }
  const result = [];
  const seen = new Set();
  for (const raw of input.projects) {
    const checked = validateProject(raw);
    const matches = existing.filter(p => expandPath(p.directory) === checked.directory);
    const old = existing.find(p => raw.id && p.id === raw.id) || (matches.length === 1 ? matches[0] : null);
    if (!old && matches.length > 1) throw new HttpError(409, `目录存在多个项目，请先整理重复项：${checked.directory}`);
    if (seen.has(checked.directory) || (old && result.some(item => item.project.id === old.id))) {
      throw new HttpError(400, `导入内容包含重复项目目录：${checked.directory}`);
    }
    seen.add(checked.directory);
    let project = checked;
    if (old) {
      const usedIds = new Set();
      const launchers = (raw.launchers ?? old.launchers).map(item => {
        const match = old.launchers.find(l => !usedIds.has(l.id) && l.id === item.id)
          || old.launchers.find(l => !usedIds.has(l.id) && l.name === item.name && l.kind === (item.kind === 'file' ? 'file' : 'command'))
          || old.launchers.find(l => !usedIds.has(l.id) && l.kind === (item.kind === 'file' ? 'file' : 'command') && (l.kind === 'file' ? l.file === item.file : l.command === item.command));
        if (match) usedIds.add(match.id);
        return { ...item, id: match?.id };
      });
      project = validateProject({ ...old, ...raw, launchers }, old);
      if (runs.some(run => run.projectId === old.id && ACTIVE.has(run.status) && !project.launchers.some(l => l.id === run.launcherId))) {
        throw new HttpError(409, `“${old.name}”仍有任务运行，请先停止要移除的启动项`);
      }
    }
    result.push({ action: old ? 'update' : 'create', project });
  }
  return result;
}

export function summarizeImport(plan) {
  return {
    count: plan.length,
    created: plan.filter(item => item.action === 'create').length,
    updated: plan.filter(item => item.action === 'update').length,
    projects: plan.map(({ action, project }) => ({ action, name: project.name, directory: project.directory, mainPanelUrl: project.mainPanelUrl, launchers: project.launchers, links: project.links })),
  };
}
